+    if (night_temp > 0.0) {
+        float t = night_temp * 100.0;              // Kelvin / 100
+        vec3 wp;
+        if (t <= 66.0) {
+            wp.r = 1.0;
+            wp.g = clamp(0.39008158 * log(t) - 0.63184144, 0.0, 1.0);
+            wp.b = (t <= 19.0)
