+        } else {
+            wp.r = clamp(1.29293618 * pow(t - 60.0, -0.1332047592), 0.0, 1.0);
+            wp.g = clamp(1.12989086 * pow(t - 60.0, -0.0755148492), 0.0, 1.0);
+            wp.b = 1.0;
+        }
+        color.rgb *= wp;
+    }
+
+    // ---- textura de papel / e-ink ----
+    if (paper_texture > 0.0) {
+        // comprime a faixa dinâmica: o preto sobe, o branco desce
+        float lo = 0.06 * paper_texture;
+        float hi = 1.0 - 0.10 * paper_texture;
+        color.rgb = lo + color.rgb * (hi - lo);
+        // grão fino, estável por pixel (não cintila entre frames)
+        float g = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
