+        // leve dessaturação, como tinta em papel
+        float ink = dot(color.rgb, vec3(0.299, 0.587, 0.114));
+        color.rgb = mix(color.rgb, vec3(ink), 0.25 * paper_texture);
+        color.rgb = clamp(color.rgb, 0.0, 1.0);
+    }
+
     // re-multiply
     color.rgb *= color.a;

