+        let _ = self.thread_command.send(ThreadCommand::ScheduleRender);
     }

// SUBSTITUI a região inteira do color_mode (greyscale + as 3 matrizes de
// daltonismo). Custo assumido: os filtros de daltonismo deixam de existir,
// além do greyscale que o patch atual já sacrifica.
//
// Mapeamento dos dois uniforms discretos que existem:
//   color_mode 1..4  -> 4 degraus de temperatura (5000K, 4000K, 3500K, 3000K)
//   invert     0/1   -> textura de papel desligada / ligada
// Os dois são switches SEPARADOS em Configurações > Acessibilidade, e
// is_noop() só é true quando ambos estão desligados -- 9 estados a quente.

    if (color_mode >= 1.0 || invert == 1.0) {
        vec3 wp = vec3(1.0, 1.0, 1.0);
        if (color_mode == 1.0) { wp = vec3(1.0, 0.90993, 0.82219); }
        else if (color_mode == 2.0) { wp = vec3(1.0, 0.82854, 0.64606); }
        else if (color_mode == 3.0) { wp = vec3(1.0, 0.77987, 0.54468); }
        else if (color_mode >= 4.0) { wp = vec3(1.0, 0.71760, 0.42107); }
        color.rgb *= wp;
        if (invert == 1.0) {
            float lo = 0.05;
            float hi = 0.92;
            color.rgb = lo + color.rgb * (hi - lo);
            float g = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
            color.rgb += (g - 0.5) * 0.030;
            float ink = dot(color.rgb, vec3(0.299, 0.587, 0.114));
            color.rgb = mix(color.rgb, vec3(ink), 0.22);
            color.rgb = clamp(color.rgb, 0.0, 1.0);
        }
    }

// E o bloco do invert original (69 bytes, em src/.../offscreen.frag:40-42)
// tem de virar no-op, porque o invert agora é a chave da textura. O
// substituto tem EXATAMENTE 69 bytes -- compara com um valor que o
// compositor nunca envia:
//
//     if (invert == 9.0) {
//         color.rgb = 1.0 - color.rgb;
//     }
//

// Cargo.toml: wayland-client = "0.31"; cosmic-protocols = { git =
//   "https://github.com/pop-os/cosmic-protocols", rev = "160b086" }
// (o mesmo rev que o cosmic-comp usa -- Cargo.toml:24 do compositor)
//
// O bind exige client_not_sandboxed (src/state.rs:762): binário nativo
// funciona, flatpak não.

use cosmic_protocols::a11y::v1::client::cosmic_a11y_manager_v1::{
    ActiveState, CosmicA11yManagerV1, Filter,
};

// Depois de bindar o global cosmic_a11y_manager_v1 na versão 2:
//
//   manager.set_screen_filter(inverted, filter);
//
// inverted: ActiveState::Enabled  -> liga a textura de papel
// filter:   Filter::Greyscale            -> degrau 1 (5000K)
//           Filter::DaltonizeProtanopia  -> degrau 2 (4000K)
//           Filter::DaltonizeDeuteranopia-> degrau 3 (3500K)
//           Filter::DaltonizeTritanopia  -> degrau 4 (3000K)
//           Filter::Disabled             -> sem temperatura
//
// ATENÇÃO (src/wayland/protocols/a11y.rs:203-211): o compositor SÓ age se o
// valor DIFERIR do estado atual. Mandar o mesmo valor duas vezes é no-op --
// não é erro, mas não force um "reaplicar" esperando repintura.

fn degrau_para_filter(n: u8) -> Filter {
    match n {
        1 => Filter::Greyscale,
        2 => Filter::DaltonizeProtanopia,
        3 => Filter::DaltonizeDeuteranopia,
        4 => Filter::DaltonizeTritanopia,
        _ => Filter::Disabled,
    }
}

// ============================================================================
// INSERÇÃO 1 — depois de `uniform float color_mode;`, fora do main()
// ============================================================================

// >>> MeowSystem: textura de papel (modo de leitura). 0.0 = desligado, 1.0 = máximo.
uniform float paper_texture;

// Hash pseudoaleatório de 1 saída a partir da coordenada de PIXEL da tela.
// Sem tempo e sem uniforms: para uma dada coordenada o valor é SEMPRE o mesmo,
// então o grão fica cravado na tela e não chuvisca entre frames -- e sobrevive
// ao damage tracking, porque a região redesenhada recalcula os mesmos valores.
//
// Por que com seno: medido nesta máquina, sin() é 1,5x a 2x MAIS BARATO que o
// hash "sem seno" do David Hoskins, porque na NVIDIA o seno é uma instrução da
// SFU e o hash sem seno são ~8 ALUs que disputam o mesmo caminho do resto.
// A precisão fp32 aguenta: testado no canto (3400,1800) de 4K, sem faixa nem
// repetição. Se um dia isto rodar em GPU móvel (mediump), trocar por:
//   vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
//   p3 += dot(p3, p3.yzx + 33.33);
//   return fract((p3.x + p3.y) * p3.z);
float meow_hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}
// <<<


// ============================================================================
// INSERÇÃO 2 — dentro do main(), depois do `if (invert == 1.0) {...}`
//              e ANTES do `if (color_mode == 1.0) {...}`
// ============================================================================

    // >>> MeowSystem: papel/Kindle. Vem ANTES do color_mode de propósito, para
    // que a luz noturna também amorne o branco do papel (senão o papel sai frio
    // e o resto quente). Custa zero medido quando paper_texture == 0.0.
    if (paper_texture > 0.0) {
        float t = clamp(paper_texture, 0.0, 1.0);

        // 1) Faixa dinâmica de PAPEL, não de tela: o preto vira tinta (~0.12,
        //    nunca 0) e o branco vira papel levemente amarelado (~0.93). É uma
        //    compressão de níveis, e é ela que tira o "brilho de OLED".
        vec3 eink = vec3(0.118, 0.113, 0.104)
                  + vec3(0.815, 0.800, 0.760) * color.rgb;

        // 2) Dessatura 30%: papel colorido nunca satura como um painel.
        //    Mantém a cor (o "Cores totais" do MIUI), só tira o exagero.
        float lum = dot(eink, vec3(0.2126, 0.7152, 0.0722));
        eink = mix(eink, vec3(lum), 0.30);

        color.rgb = mix(color.rgb, eink, t);

        // 3) Grão. gl_FragCoord.xy é a coordenada de PIXEL do monitor: não anda
        //    quando a janela anda (v_coords andaria), não anda entre frames.
        //    Duas oitavas: uma fina (poro) e uma grossa a ~1/3 de escala (fibra).
        //    Uma oitava só já funciona e custa metade; três dão fibra mais rica
        //    e custam +0,074 ms -- ainda barato, é escolha de gosto.
        vec2 pix = floor(gl_FragCoord.xy);
        float g = (meow_hash(pix) + meow_hash(floor(pix * 0.34) + 11.0)) * 0.5 - 0.5;

        // 4) Multiplicativo, não aditivo: papel modula a REFLETÂNCIA. Assim o
        //    grão aparece no branco e some na tinta, que é o comportamento real
        //    -- e o texto não serrilha. Amplitude ~4 níveis de 255 no papel,
        //    o que de quebra funciona como dither e mata banding.
        color.rgb *= 1.0 + g * (0.085 * t);
        color.rgb = clamp(color.rgb, 0.0, 1.0);
