// RANDOM_SCALE = vec4(.1031, .1030, .0973, .1099)  <-- a variante
// RANDOM_HIGHER_RANGE, que é a CERTA para coordenada de tela (0..3840):
// multiplicar por um número PEQUENO antes do fract mantém o valor abaixo de
// 1 e preserva mantissa. A escala default (443.897, 441.423, ...) é só para
// entrada já normalizada em 0..1 e vai borrar em 4K.
float random(in vec2 st) {
    vec3 p3 = fract(vec3(st.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
