// --- Bayer 4x4. A indexação DINÂMICA b[x][y] compila em #version 100 nos
//     dois drivers desta máquina, apesar de a ES 1.00 só garantir índice
//     constante. Ou seja: portável na prática, frágil no papel.
float getBayer(vec2 pos) {
    int x = int(mod(pos.x, 4.0));
    int y = int(mod(pos.y, 4.0));
    const mat4 bayer = mat4( 0.0, 12.0,  3.0, 15.0,
                             8.0,  4.0, 11.0,  7.0,
                             2.0, 14.0,  1.0, 13.0,
                            10.0,  6.0,  9.0,  5.0);
    return bayer[x][y] / 16.0;
}

// --- Fibra de papel em 5 oitavas (aqui mora o custo: 5 hashes)
float paperTexture(vec2 uv) {
    float n = 0.0;
    n += hash(uv *  0.3) * 0.6;   // fibras muito grandes
    n += hash(uv *  0.8) * 0.4;   // fibras grandes
    n += hash(uv *  2.5) * 0.3;   // detalhe médio
    n += hash(uv *  6.0) * 0.2;   // grão fino
    n += hash(uv * 15.0) * 0.1;   // grão muito fino
    return n / 1.6;
}

// --- Grão direcional: simula a fibra correndo numa direção (+2 hashes)
float directionalGrain(vec2 uv) {
    vec2 direction = vec2(0.7, 0.3);
    float grain = 0.0;
    grain += hash(uv * 3.0 + direction * 2.0) * 0.5;
    grain += hash(uv * 8.0 + direction * 5.0) * 0.3;
    return grain / 0.8;
}

// --- A curva de resposta e-ink e a paleta tinta/papel (o miolo do efeito)
