    float gray = dot(pixColor.rgb, vec3(0.299, 0.587, 0.114));
    gray = pow(gray, 1.2);                    // e-ink não é linear
    gray = smoothstep(0.08, 0.92, gray);      // curva S: corta preto/branco puros
    float midBoost = smoothstep(0.3,0.5,gray) * (1.0 - smoothstep(0.5,0.7,gray));
    gray += midBoost * 0.1;

    vec2 screenPos = gl_FragCoord.xy;         // <-- ancorado em pixel de tela
    float textureMask = smoothstep(0.5, 0.95, gray);   // grão só no papel
    gray += (paperTexture(screenPos * 0.3) - 0.5) * 0.035 * textureMask;
    gray += (directionalGrain(screenPos * 0.4) - 0.5) * 0.025 * textureMask * 0.7;
    gray += (getBayer(screenPos) - 0.5) * 0.025 * textureMask;

    vec3 paperColor = vec3(0.94, 0.92, 0.86);
    vec3 inkColor   = vec3(0.10, 0.10, 0.12);
    gl_FragColor = vec4(mix(inkColor, paperColor, clamp(gray,0.0,1.0)), pixColor.a);
}

