    color.b *= 1.0 - (WARMTH * 0.7);   // derruba azul
    color.g *= 1.0 - (WARMTH * 0.3);   // derruba verde um pouco
    color.r *= 1.0 + (WARMTH * 0.1);   // levanta vermelho
    color.rgb *= INTENSITY;
