// Forma SEGURA em ES 1.00: cadeia de mix/step, zero indexação de array.
// (LYGIA usa exatamente isto no ramo PLATFORM_WEBGL, pelo mesmo motivo.)
float ditherBayer4(vec2 xy) {
    float x = mod(xy.x, 4.0);
    float y = mod(xy.y, 4.0);
    float a = mix(mix( 0.0, 12.0, step(1.0,y)), mix( 3.0, 15.0, step(3.0,y)), step(2.0,y));
    float b = mix(mix( 8.0,  4.0, step(1.0,y)), mix(11.0,  7.0, step(3.0,y)), step(2.0,y));
    float c = mix(mix( 2.0, 14.0, step(1.0,y)), mix( 1.0, 13.0, step(3.0,y)), step(2.0,y));
    float d = mix(mix(10.0,  6.0, step(1.0,y)), mix( 9.0,  5.0, step(3.0,y)), step(2.0,y));
    return mix(mix(a,b,step(1.0,x)), mix(c,d,step(3.0,x)), step(2.0,x)) / 16.0;
